"""
    Calculate anisotropy from vertical (vv), horizontal (vh), and empirical
    G-factor (G).
    """
def calculate_r(vv: Any, vh: Any, G: Any = 1.0) -> object {
    return ((vv - (G * vh)) / (vv + (2 * G * vh)));
}

